from pathlib import Path
import subprocess, shutil, math

ROOT = Path('/root/verge')
OUT = ROOT / 'artifacts/verge-intro'
FRAMES = OUT / 'frames'
OUT.mkdir(parents=True, exist_ok=True)
if FRAMES.exists(): shutil.rmtree(FRAMES)
FRAMES.mkdir()

html = r'''<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box} html,body,#stage{margin:0;width:1920px;height:1080px;overflow:hidden;background:#090b0a;color:#f5f7f4;font-family:Arial,sans-serif}.stage{position:relative;width:100%;height:100%;background:radial-gradient(ellipse at 50% 45%,#17342b 0%,#0d1613 38%,#080a09 76%);overflow:hidden}.grain{position:absolute;inset:0;opacity:.14;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.95' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.orb{position:absolute;border-radius:50%;filter:blur(34px);background:#5ee9b0;opacity:.1}.line{position:absolute;height:1px;background:linear-gradient(90deg,transparent,#9af4c8,transparent);opacity:.25}.eyebrow{position:absolute;top:90px;left:110px;font:600 15px monospace;letter-spacing:5px;color:#95d9b8}.brand{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:28px}.brand img{width:132px;height:132px;object-fit:contain;border-radius:28px}.brand .name{font-size:110px;letter-spacing:16px;font-weight:500}.sub{position:absolute;left:50%;top:625px;transform:translateX(-50%);font:400 25px monospace;letter-spacing:3px;color:#b1c6ba;white-space:nowrap}.big{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:116px;line-height:1.04;text-align:center;letter-spacing:-5px;font-weight:500;width:1500px}.big em{font-style:normal;color:#8aefbd}.small{position:absolute;left:50%;top:690px;transform:translateX(-50%);font-size:25px;line-height:1.5;text-align:center;color:#afbbb4;width:930px}.node{position:absolute;width:210px;height:210px;border-radius:34px;background:rgba(18,24,21,.82);border:1px solid rgba(181,255,212,.22);display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 20px 80px rgba(0,0,0,.35)}.node img{width:80px;height:80px;object-fit:contain;border-radius:18px}.node span{margin-top:14px;font:600 15px monospace;letter-spacing:2px;color:#d6e6dc}.rail{position:absolute;left:410px;top:522px;width:1100px;height:2px;background:rgba(162,243,190,.25)}.packet{position:absolute;width:24px;height:24px;border-radius:50%;background:#8af1bc;box-shadow:0 0 38px #68f0a8}.cap{position:absolute;left:50%;transform:translateX(-50%);top:830px;border:1px solid rgba(178,240,199,.24);padding:14px 20px;border-radius:999px;font:600 14px monospace;letter-spacing:2px;color:#a7c5b4}.logo-row{position:absolute;left:50%;top:505px;transform:translateX(-50%);display:flex;gap:52px;align-items:center}.chip{width:150px;height:150px;border:1px solid rgba(255,255,255,.11);background:rgba(18,23,21,.72);border-radius:31px;display:flex;align-items:center;justify-content:center}.chip img{max-width:96px;max-height:96px;object-fit:contain;border-radius:18px}.rail-label{position:absolute;left:50%;top:725px;transform:translateX(-50%);font:600 18px monospace;letter-spacing:4px;color:#a7c5b4;white-space:nowrap}.footer{position:absolute;bottom:82px;left:110px;right:110px;display:flex;justify-content:space-between;font:600 14px monospace;letter-spacing:3px;color:#74887c}.cta{position:absolute;left:50%;top:675px;transform:translateX(-50%);padding:22px 34px;border-radius:13px;background:#9af3c5;color:#08110c;font:700 20px monospace;letter-spacing:2px}.pulse{position:absolute;border:1px solid #8aefbd;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%)}
</style></head><body><div id="stage"></div><script>
const A='./public/'; const V=A+'verge-logo.jpeg', R=A+'logos/robinhood.jpg', M=A+'logos/morpho.jpg', C=A+'logos/circle.jpg', B=A+'chains/base.png', S=A+'chains/solana.png';
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x)); const e=x=>{x=clamp(x);return x*x*(3-2*x)}; const fade=(t,a,b)=>e((t-a)/(b-a)); const inv=(t,a,b)=>1-fade(t,a,b); const esc=s=>s; const style=(o)=>Object.entries(o).map(([k,v])=>`${k}:${v}`).join(';');
function shell(inner){return `<div class="stage"><div class="grain"></div><div class="orb" style="width:620px;height:620px;left:calc(50% - 310px);top:calc(50% - 310px)"></div><div class="line" style="top:150px;left:0;width:100%"></div>${inner}<div class="footer"><span>VERGE / x402</span><span>PAYMENTS FOR SOFTWARE</span></div></div>`}
function scene(t){let x='';
if(t<2.2){let p=fade(t,.15,1.2),q=fade(t,1.25,2.1);x=`<div class="eyebrow" style="opacity:${p}">INTRODUCING</div><div class="brand" style="opacity:${p};transform:translate(-50%,-50%) scale(${.88+.12*p})"><img src="${V}"><div class="name">VERGE</div></div><div class="sub" style="opacity:${q};transform:translateX(-50%) translateY(${16*(1-q)}px)">PAYMENT RAILS FOR THE AGENT ECONOMY</div>`}
else if(t<4.7){let p=fade(t,2.25,3.0),q=fade(t,3.25,4.1);x=`<div class="eyebrow">THE PROTOCOL</div><div class="big" style="opacity:${p};transform:translate(-50%,-50%) translateY(${28*(1-p)}px)">ONE REQUEST.<br><em>ONE SETTLEMENT.</em></div><div class="small" style="opacity:${q}">An API responds with HTTP 402. Software pays the required stablecoin, proves the transaction, and unlocks access.</div>`}
else if(t<7.5){let p=fade(t,4.8,5.35); let pos=410+1100*clamp((t-5.35)/1.55);x=`<div class="eyebrow">THE REAL MECHANISM</div><div class="node" style="left:200px;top:420px;opacity:${p}"><img src="${V}"><span>CALLER</span></div><div class="node" style="left:1510px;top:420px;opacity:${p}"><img src="${R}"><span>SETTLEMENT</span></div><div class="rail" style="opacity:${p}"></div><div class="packet" style="left:${pos}px;top:511px;opacity:${p}"></div><div class="cap" style="opacity:${fade(t,5.3,5.8)}">REQUEST → 402 CHALLENGE → USDG → PROOF RETRY → 200</div>`}
else if(t<9.9){let p=fade(t,7.6,8.2); x=`<div class="eyebrow">MULTICHAIN BY DESIGN</div><div class="big" style="font-size:76px;top:330px;opacity:${p}">CHOOSE THE RAIL.<br><em>KEEP THE FLOW.</em></div><div class="logo-row" style="opacity:${p}">${[R,M,C,B,S].map((z,i)=>`<div class="chip" style="transform:translateY(${20*(1-p)+Math.sin(t*2+i)*3}px)"><img src="${z}"></div>`).join('')}</div><div class="rail-label" style="opacity:${fade(t,8.25,8.8)}">ROBINHOOD · MORPHO · CIRCLE · BASE · SOLANA</div>`}
else {let p=fade(t,10.05,10.7),q=fade(t,10.8,11.35);x=`<div class="eyebrow" style="opacity:${p}">VERGE</div><div class="brand" style="top:415px;opacity:${p};transform:translate(-50%,-50%) scale(${.9+.1*p})"><img src="${V}"><div class="name" style="font-size:82px">VERGE</div></div><div class="sub" style="top:560px;opacity:${q}">HTTP 402 FOR AGENTS, APPS, AND APIs.</div><div class="cta" style="opacity:${q};transform:translateX(-50%) translateY(${12*(1-q)}px)">vergesnowy.com</div>`}
return shell(x)} window.seek=t=>document.querySelector('#stage').innerHTML=scene(t);window.seek(0);
</script></body></html>'''
(OUT/'index.html').write_text(html)
# file URL works for assets when base points root; make asset aliases via symlink
assets=OUT/'public'
if assets.exists() or assets.is_symlink(): assets.unlink() if assets.is_symlink() else shutil.rmtree(assets)
assets.symlink_to(ROOT/'public',target_is_directory=True)
# render playwright node script
node = '''const { chromium }=require("playwright"); const fs=require("fs"); (async()=>{const b=await chromium.launch({headless:true});const p=await b.newPage({viewport:{width:1920,height:1080},deviceScaleFactor:1}); await p.goto("file:///root/verge/artifacts/verge-intro/index.html"); for(let i=0;i<360;i++){await p.evaluate(t=>window.seek(t),i/30);await p.screenshot({path:`/root/verge/artifacts/verge-intro/frames/f_${String(i).padStart(4,"0")}.png`});}await b.close()})().catch(e=>{console.error(e);process.exit(1)});'''
(OUT/'render.js').write_text(node)
subprocess.run(['node',str(OUT/'render.js')],cwd=ROOT,check=True)
subprocess.run(['ffmpeg','-y','-framerate','30','-i',str(FRAMES/'f_%04d.png'),'-c:v','libx264','-preset','medium','-crf','17','-pix_fmt','yuv420p',str(OUT/'video.mp4')],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
print(OUT/'video.mp4')
